def selected_action_text(operation,resource,language='fr'):
    en=language=='en';verb={('edit',False):'Modifier',('delete',False):'Supprimer',('edit',True):'Edit',('delete',True):'Delete'}[(operation,en)]
    return verb+' · '+RESOURCE_LABELS[resource][int(en)]
